#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long s;
    cin >> n >> s;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    int best = 0, l = 0;
    long long total = 0;
    for (int rr = 0; rr < n; rr++) {
        total += a[rr];
        while (total >= s) {
            int length = rr - l + 1;
            if (best == 0 || length < best) best = length;
            total -= a[l];
            l++;
        }
    }
    cout << best << "\n";

    return 0;
}

